double PolyValue(double a[], int n, double x) {
    double p = a[n];                 /* 从最高次项系数开始 */
    for (int i = n - 1; i >= 0; i--)
        p = p * x + a[i];            /* 每层一次乘、一次加 */
    return p;
}

void Reverse(int a[], int left, int right) {
    while (left < right) {
        int t = a[left];
        a[left++] = a[right];
        a[right--] = t;
    }
}

void LeftShift(int a[], int n, int k) {
    if (n <= 1) return;
    k = k % n;                       /* k >= n 时先取模，避免无效趟次 */
    Reverse(a, 0, k - 1);
    Reverse(a, k, n - 1);
    Reverse(a, 0, n - 1);
}

int HasDuplicate(int a[], int n) {
    if (n <= 1) return 0;
    MergeSort(a, 0, n - 1);          /* 任一 O(nlog n) 排序 */
    for (int i = 1; i < n; i++)
        if (a[i] == a[i - 1]) return 1;
    return 0;
}

int Intersect(int A[], int m, int B[], int n, int C[]) {
    int i = 0, j = 0, k = 0;
    while (i < m && j < n) {
        if (A[i] < B[j]) i++;
        else if (A[i] > B[j]) j++;
        else { C[k++] = A[i]; i++; j++; }
    }
    return k;                        /* 返回交集的元素个数 */
}

void ReverseList(SqList *L) {
    int i = 0, j = L->length - 1;
    ElemType t;
    while (i < j) {
        t = L->elem[i];
        L->elem[i] = L->elem[j];
        L->elem[j] = t;
        i++; j--;
    }
}

Status InsertOrder(SqList *L, ElemType x) {
    int low = 0, high = L->length - 1, mid, i;
    if (L->length >= MAXSIZE) return ERROR;      /* 表满 */
    while (low <= high) {                        /* 找第一个大于 x 的位置 */
        mid = (low + high) / 2;
        if (L->elem[mid] <= x) low = mid + 1;
        else high = mid - 1;
    }
    for (i = L->length; i > low; i--)            /* 从后往前后移 */
        L->elem[i] = L->elem[i - 1];
    L->elem[low] = x;
    L->length++;
    return OK;
}

void ReverseLinkList(LinkList L) {
    LinkList p = L->next, q;
    L->next = NULL;                  /* 新表初始为空 */
    while (p != NULL) {
        q = p->next;                 /* 暂存后继，防止断链 */
        p->next = L->next;           /* 头插 */
        L->next = p;
        p = q;                       /* 前进 */
    }
}

void DeleteX(LinkList L, ElemType x) {
    LinkList pre = L, p = L->next, q;
    while (p != NULL) {
        if (p->data == x) {
            q = p;
            pre->next = p->next;
            p = pre->next;           /* pre 不动，继续检查新 p */
            free(q);
        } else {
            pre = p;
            p = p->next;
        }
    }
}

#define MAXSIZE 100
typedef struct {
    ElemType data[MAXSIZE];
    int top;                          /* 栈顶元素的下一个位置 */
} SqStack;

Status InitStack(SqStack *S) { S->top = 0; return OK; }
int StackEmpty(SqStack S) { return S.top == 0; }
int StackLength(SqStack S) { return S.top; }

Status Push(SqStack *S, ElemType e) {
    if (S->top >= MAXSIZE) return ERROR;    /* 栈满 */
    S->data[S->top++] = e;
    return OK;
}

Status Pop(SqStack *S, ElemType *e) {
    if (S->top == 0) return ERROR;          /* 栈空 */
    *e = S->data[--S->top];
    return OK;
}

Status GetTop(SqStack S, ElemType *e) {
    if (S.top == 0) return ERROR;
    *e = S.data[S.top - 1];
    return OK;
}

#define MAXSIZE 100
typedef struct {
    ElemType data[MAXSIZE];
    int front, rear;
} SqQueue;

Status InitQueue(SqQueue *Q) { Q->front = Q->rear = 0; return OK; }
int QueueEmpty(SqQueue Q) { return Q.front == Q.rear; }
int QueueFull(SqQueue Q) { return (Q.rear + 1) % MAXSIZE == Q.front; }
int QueueLength(SqQueue Q) { return (Q.rear - Q.front + MAXSIZE) % MAXSIZE; }

Status EnQueue(SqQueue *Q, ElemType e) {
    if ((Q->rear + 1) % MAXSIZE == Q->front) return ERROR;
    Q->data[Q->rear] = e;
    Q->rear = (Q->rear + 1) % MAXSIZE;
    return OK;
}

Status DeQueue(SqQueue *Q, ElemType *e) {
    if (Q->front == Q->rear) return ERROR;
    *e = Q->data[Q->front];
    Q->front = (Q->front + 1) % MAXSIZE;
    return OK;
}

int BracketMatch(char s[], int n) {
    SqStack S; ElemType e;
    InitStack(&S);
    for (int i = 0; i < n; i++) {
        if (s[i]=='(' || s[i]=='[' || s[i]=='{') Push(&S, s[i]);
        else if (s[i]==')' || s[i]==']' || s[i]=='}') {
            if (StackEmpty(S)) return i + 1;          /* 右括号多余 */
            Pop(&S, &e);
            if ((s[i]==')' && e!='(') || (s[i]==']' && e!='[') || (s[i]=='}' && e!='{'))
                return i + 1;                          /* 类型不匹配 */
        }
    }
    return StackEmpty(S) ? 0 : n + 1;                  /* 0 表示配对正确 */
}

double EvalRPN(char s[], int n) {
    double stack[MAXSIZE], a, b;
    int top = 0;
    for (int i = 0; i < n; i++) {
        if (s[i] >= '0' && s[i] <= '9') stack[top++] = s[i] - '0';
        else if (s[i]==' ' || s[i]=='\t') continue;
        else {
            b = stack[--top];                 /* 右操作数 */
            a = stack[--top];                 /* 左操作数 */
            switch (s[i]) {
                case '+': stack[top++] = a + b; break;
                case '-': stack[top++] = a - b; break;
                case '*': stack[top++] = a * b; break;
                case '/': if (b == 0) return 0.0/0.0;
                          stack[top++] = a / b; break;
            }
        }
    }
    return stack[--top];
}

#define MAXSTRLEN 255
typedef unsigned char SString[MAXSTRLEN + 1];   /* 0 号单元存长度 */

Status StrAssign(SString T, char *chars) {
    int i;
    for (i = 0; chars[i] != '\0' && i < MAXSTRLEN; i++)
        T[i + 1] = chars[i];
    T[0] = i;
    return OK;
}

int StrLength(SString S) { return S[0]; }

Status Concat(SString T, SString S1, SString S2) {
    int i;
    if (S1[0] + S2[0] <= MAXSTRLEN) {          /* 未超出 */
        for (i = 1; i <= S1[0]; i++) T[i] = S1[i];
        for (i = 1; i <= S2[0]; i++) T[S1[0] + i] = S2[i];
        T[0] = S1[0] + S2[0];
        return OK;
    } else if (S1[0] < MAXSTRLEN) {            /* S2 部分截断 */
        for (i = 1; i <= S1[0]; i++) T[i] = S1[i];
        for (i = 1; i <= MAXSTRLEN - S1[0]; i++) T[S1[0] + i] = S2[i];
        T[0] = MAXSTRLEN;
        return ERROR;
    } else {                                    /* S1 已满，S2 全部舍弃 */
        for (i = 1; i <= MAXSTRLEN; i++) T[i] = S1[i];
        T[0] = MAXSTRLEN;
        return ERROR;
    }
}

Status SubString(SString Sub, SString S, int pos, int len) {
    int i;
    if (pos < 1 || pos > S[0] || len < 0 || pos + len - 1 > S[0])
        return ERROR;
    for (i = 1; i <= len; i++) Sub[i] = S[pos + i - 1];
    Sub[0] = len;
    return OK;
}

int Index_BF(SString S, SString T, int pos) {
    int i = pos, j = 1;
    while (i <= S[0] && j <= T[0]) {
        if (S[i] == T[j]) { i++; j++; }        /* 继续比较后继字符 */
        else { i = i - j + 2; j = 1; }         /* 指针回退，重新开始 */
    }
    if (j > T[0]) return i - T[0];             /* 匹配成功 */
    return 0;                                  /* 失败 */
}

void GetNext(SString T, int next[]) {
    int i = 1, j = 0;
    next[1] = 0;
    while (i < T[0]) {
        if (j == 0 || T[i] == T[j]) { i++; j++; next[i] = j; }
        else j = next[j];                       /* 前缀回退 */
    }
}

int Index_KMP(SString S, SString T, int pos) {
    int next[MAXSTRLEN + 1];
    int i = pos, j = 1;
    GetNext(T, next);
    while (i <= S[0] && j <= T[0]) {
        if (j == 0 || S[i] == T[j]) { i++; j++; }
        else j = next[j];                       /* 主串指针不回退 */
    }
    if (j > T[0]) return i - T[0];
    return 0;
}

void CharCount(SString S, int cnt[]) {
    int i;
    for (i = 0; i < 256; i++) cnt[i] = 0;
    for (i = 1; i <= S[0]; i++) cnt[(unsigned char)S[i]]++;
}

void DeleteChar(SString S, char c) {
    int i, k = 1;
    for (i = 1; i <= S[0]; i++)
        if (S[i] != c) S[k++] = S[i];
    S[0] = k - 1;
}

#define MAXSIZE 1000
typedef struct { int i, j; ElemType e; } Triple;
typedef struct { Triple data[MAXSIZE + 1]; int mu, nu, tu; } TSMatrix;

Status FastTranspose(TSMatrix M, TSMatrix *T) {
    int num[MAXSIZE], cpot[MAXSIZE], col, t, q;
    T->mu = M.nu; T->nu = M.mu; T->tu = M.tu;
    if (T->tu == 0) return OK;
    for (col = 1; col <= M.nu; col++) num[col] = 0;
    for (t = 1; t <= M.tu; t++) num[M.data[t].j]++;       /* 统计每列非零元个数 */
    cpot[1] = 1;
    for (col = 2; col <= M.nu; col++)
        cpot[col] = cpot[col - 1] + num[col - 1];          /* 求每列首个元素的存放位置 */
    for (t = 1; t <= M.tu; t++) {
        col = M.data[t].j;
        q = cpot[col];
        T->data[q].i = M.data[t].j;                        /* 行列互换 */
        T->data[q].j = M.data[t].i;
        T->data[q].e = M.data[t].e;
        cpot[col]++;
    }
    return OK;
}

Status AddTSMatrix(TSMatrix A, TSMatrix B, TSMatrix *C) {
    if (A.mu != B.mu || A.nu != B.nu) return ERROR;
    int pa = 1, pb = 1, pc = 0;
    ElemType sum;
    while (pa <= A.tu && pb <= B.tu) {
        if (A.data[pa].i < B.data[pb].i ||
           (A.data[pa].i == B.data[pb].i && A.data[pa].j < B.data[pb].j)) {
            C->data[++pc] = A.data[pa++];
        } else if (A.data[pa].i > B.data[pb].i ||
                  (A.data[pa].i == B.data[pb].i && A.data[pa].j > B.data[pb].j)) {
            C->data[++pc] = B.data[pb++];
        } else {                                   /* 位置相同 */
            sum = A.data[pa].e + B.data[pb].e;
            if (sum != 0) {
                C->data[++pc] = A.data[pa];
                C->data[pc].e = sum;
            }
            pa++; pb++;
        }
    }
    while (pa <= A.tu) C->data[++pc] = A.data[pa++];   /* 处理剩余部分 */
    while (pb <= B.tu) C->data[++pc] = B.data[pb++];
    C->mu = A.mu; C->nu = A.nu; C->tu = pc;
    return OK;
}

typedef enum { ATOM, LIST } ElemTag;
typedef struct GLNode {
    ElemTag tag;
    union {
        char atom;
        struct { struct GLNode *hp, *tp; } ptr;
    } un;
} *GList;

int GListDepth(GList L) {
    int max = 0, dep;
    GList p;
    if (L == NULL) return 1;                   /* 空表深度为 1 */
    if (L->tag == ATOM) return 0;              /* 原子深度为 0 */
    for (p = L; p != NULL; p = p->un.ptr.tp) { /* 沿表尾指针遍历各元素 */
        dep = GListDepth(p->un.ptr.hp);        /* 对表头递归求深度 */
        if (dep > max) max = dep;
    }
    return max + 1;                            /* 各元素深度的最大值加 1 */
}

typedef struct { ElemType sa[MAXLEN]; int n; } SymMatrix;

int Index(int i, int j) {                      /* (i,j) -> k，下标从 1 开始 */
    int t;
    if (i < j) { t = i; i = j; j = t; }        /* 利用对称性 */
    return i * (i - 1) / 2 + j - 1;
}

void Locate(int k, int *i, int *j) {           /* k -> (i,j) */
    int row = 1;
    while (k >= row * (row + 1) / 2) row++;    /* 找 k 所在的行 */
    *i = row;
    *j = k - row * (row - 1) / 2 + 1;
}

ElemType Get(SymMatrix M, int i, int j) { return M.sa[Index(i, j)]; }

void Set(SymMatrix *M, int i, int j, ElemType e) {
    M->sa[Index(i, j)] = e;                    /* 对称位置自动同步 */
}

